import rules_lib

def check(ctx):
    first_time_homebuyer = ctx['Borrower.is_first_time_homebuyer']
    missing = rules_lib.gaps(first_time_homebuyer=first_time_homebuyer)
    if missing:
        return rules_lib.unknown(*missing)

    first_time_homebuyer = rules_lib.flag(first_time_homebuyer)
    if first_time_homebuyer is None:
        return rules_lib.unknown('first_time_homebuyer')
    if not first_time_homebuyer:
        return True

    reserves_months = ctx['RatioSet.reserves_months']
    missing = rules_lib.gaps(reserves_months=reserves_months)
    if missing:
        return rules_lib.unknown(*missing)

    return reserves_months >= 6

