def check(ctx):
    score = ctx['CreditReport.representative_score']
    missing = rules_lib.gaps(score=score)
    if missing:
        return rules_lib.unknown(*missing)

    if score < 620:
        reserves_months = ctx['RatioSet.reserves_months']
        missing = rules_lib.gaps(reserves_months=reserves_months)
        if missing:
            return rules_lib.unknown(*missing)
        return reserves_months >= 12

    return True

import decimal
import rules_lib


def check(ctx):
    cltv = ctx['LoanCore.cltv_percent']
    loan_purpose = ctx['LoanCore.loan_purpose']

    missing = rules_lib.gaps(cltv=cltv, loan_purpose=loan_purpose)
    if missing:
        return rules_lib.unknown(*missing)

    try:
        cltv_value = decimal.Decimal(str(cltv))
    except (decimal.InvalidOperation, TypeError, ValueError):
        return rules_lib.unknown('LoanCore.cltv_percent')
    if not cltv_value.is_finite():
        return rules_lib.unknown('LoanCore.cltv_percent')

    if cltv_value <= 70:
        return True
    if not rules_lib.same(loan_purpose, 'business purpose'):
        return True

    # No permitted case field supplies funds to close, so the $50,000 trigger
    # cannot be decided for a business-purpose loan above 70% CLTV.
    return rules_lib.unknown('funds_to_close')

def check(ctx):
    vacant = ctx['SubjectProperty.is_vacant']
    purpose = ctx['LoanCore.loan_purpose']
    missing = rules_lib.gaps(vacant=vacant, purpose=purpose)
    if missing:
        return rules_lib.unknown(*missing)

    vacant_flag = rules_lib.flag(vacant)
    if vacant_flag is None:
        return rules_lib.unknown('vacant')
    if not vacant_flag:
        return True

    is_rate_term = rules_lib.same(purpose, 'rate and term refinance', 'rate & term refinance')
    is_cash_out = rules_lib.same(purpose, 'cash-out refinance')
    if not (is_rate_term or is_cash_out):
        return True

    reserves = ctx['RatioSet.reserves_months']
    missing = rules_lib.gaps(reserves=reserves)
    if missing:
        return rules_lib.unknown(*missing)
    return reserves >= 6

