def check(ctx):
    amount = ctx['LoanCore.total_loan_amount_usd']
    cltv_percent = ctx['LoanCore.cltv_percent']
    representative_score = ctx['CreditReport.representative_score']
    mortgage_0x30x24 = ctx['CreditReport.mortgage_0x30x24']

    missing = rules_lib.gaps(
        amount=amount,
        cltv_percent=cltv_percent,
        representative_score=representative_score,
        mortgage_0x30x24=mortgage_0x30x24,
    )
    if missing:
        return rules_lib.unknown(*missing)

    history_ok = rules_lib.flag(mortgage_0x30x24)
    if history_ok is None:
        return rules_lib.unknown('mortgage_0x30x24')

    return (
        amount <= 1500000
        and cltv_percent <= 80
        and representative_score >= 700
        and history_ok
    )

