def check(ctx):
    cltv = ctx['LoanCore.cltv_percent']
    missing = rules_lib.gaps(cltv=cltv)
    if missing:
        return rules_lib.unknown(*missing)

    above_70 = rules_lib.band(cltv, [(70, False)], above=True)
    if above_70 is None:
        return rules_lib.unknown('LoanCore.cltv_percent')
    if not above_70:
        return True

    purpose = ctx['LoanCore.loan_purpose']
    missing = rules_lib.gaps(purpose=purpose)
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(purpose, 'consumer'):
        return rules_lib.unknown('seasoning_verification')
    if rules_lib.same(purpose, 'business purpose'):
        return rules_lib.unknown('funds_to_close', 'seasoning_verification')
    return rules_lib.unknown('LoanCore.loan_purpose')

import rules_lib

def check(ctx):
    io_raw = ctx['MortgageLoanInformation.is_interest_only']
    missing = rules_lib.gaps(**{'MortgageLoanInformation.is_interest_only': io_raw})
    if missing:
        return rules_lib.unknown(*missing)
    io = rules_lib.flag(io_raw)
    if io is None:
        return rules_lib.unknown('MortgageLoanInformation.is_interest_only')
    if not io:
        return True

    term_raw = ctx['LoanCore.is_interest_only_10_40']
    amount_raw = ctx['LoanCore.total_loan_amount_usd']
    first_time_raw = ctx['Borrower.is_first_time_homebuyer']
    vacant_raw = ctx['SubjectProperty.is_vacant']
    listed_raw = ctx['SubjectProperty.is_listed_for_sale']
    missing = rules_lib.gaps(**{
        'LoanCore.is_interest_only_10_40': term_raw,
        'LoanCore.total_loan_amount_usd': amount_raw,
        'Borrower.is_first_time_homebuyer': first_time_raw,
        'SubjectProperty.is_vacant': vacant_raw,
        'SubjectProperty.is_listed_for_sale': listed_raw,
    })
    if missing:
        return rules_lib.unknown(*missing)

    is_10_40 = rules_lib.flag(term_raw)
    first_time = rules_lib.flag(first_time_raw)
    vacant = rules_lib.flag(vacant_raw)
    listed = rules_lib.flag(listed_raw)
    if is_10_40 is None:
        return rules_lib.unknown('LoanCore.is_interest_only_10_40')
    if first_time is None:
        return rules_lib.unknown('Borrower.is_first_time_homebuyer')
    if vacant is None:
        return rules_lib.unknown('SubjectProperty.is_vacant')
    if listed is None:
        return rules_lib.unknown('SubjectProperty.is_listed_for_sale')

    amount = rules_lib.ratio(amount_raw, 1)
    if amount is None:
        return rules_lib.unknown('LoanCore.total_loan_amount_usd')
    if amount < 250_000:
        return False
    if is_10_40 and amount > 3_000_000:
        return False

    if first_time or listed:
        return False

    if vacant:
        purpose = ctx['LoanCore.loan_purpose']
        missing = rules_lib.gaps(**{'LoanCore.loan_purpose': purpose})
        if missing:
            return rules_lib.unknown(*missing)
        if any(rules_lib.same(purpose, value) for value in (
            'refinance', 'cash-out refinance', 'rate/term refinance',
            'limited cash-out refinance', 'cash-out refi', 'rate/term refi',
        )):
            return False

    if is_10_40:
        ltv = ctx['LoanCore.cltv_percent']
        missing = rules_lib.gaps(**{'LoanCore.cltv_percent': ltv})
        if missing:
            return rules_lib.unknown(*missing)
        ltv = rules_lib.ratio(ltv, 1)
        if ltv is None:
            return rules_lib.unknown('LoanCore.cltv_percent')
        if ltv > 80:
            return False

    return True

import rules_lib


def check(ctx):
    listed_raw = ctx['SubjectProperty.listed_for_sale_last_6_months']
    reserves = ctx['RatioSet.reserves_months']
    interest_only_raw = ctx['MortgageLoanInformation.is_interest_only']

    missing = rules_lib.gaps(
        listed=listed_raw,
        reserves=reserves,
        interest_only=interest_only_raw,
    )
    if missing:
        return rules_lib.unknown(*missing)

    listed = rules_lib.flag(listed_raw)
    interest_only = rules_lib.flag(interest_only_raw)
    if listed is None or interest_only is None:
        undecided = []
        if listed is None:
            undecided.append('SubjectProperty.listed_for_sale_last_6_months')
        if interest_only is None:
            undecided.append('MortgageLoanInformation.is_interest_only')
        return rules_lib.unknown(*undecided)

    reserve_ratio = rules_lib.ratio(reserves, 24)
    if reserve_ratio is None:
        return rules_lib.unknown('RatioSet.reserves_months')

    return listed and reserve_ratio >= 1 and not interest_only

