import re
import rules_lib

def check(ctx):
    purpose = ctx['LoanCore.loan_purpose']
    subtype = ctx['SubjectProperty.occupancy_subtype']
    vacant_raw = ctx['SubjectProperty.is_vacant']
    missing = rules_lib.gaps(purpose=purpose, subtype=subtype, vacant=vacant_raw)
    if missing:
        return rules_lib.unknown(*missing)

    vacant = rules_lib.flag(vacant_raw)
    if vacant is None:
        return rules_lib.unknown('SubjectProperty.is_vacant')
    if not vacant or not rules_lib.same(purpose, 'refinance', 'rate and term refinance', 'cash out refinance'):
        return False

    if rules_lib.same(subtype, 'rate and term', 'rate/term', 'rate and term refinance'):
        kind = 'rate_term'
    elif rules_lib.same(subtype, 'cash out', 'cash-out', 'cash out refinance'):
        kind = 'cash_out'
    else:
        return rules_lib.unknown('SubjectProperty.occupancy_subtype')

    amount_raw = ctx['LoanCore.total_loan_amount_usd']
    cltv_raw = ctx['LoanCore.cltv_percent']
    score_raw = ctx['CreditReport.representative_score']
    interest_only_raw = ctx['MortgageLoanInformation.is_interest_only']
    escrow_waived_raw = ctx['LoanCore.is_escrow_waived']
    reserves_raw = ctx['RatioSet.reserves_months']
    penalty_raw = ctx['LoanCore.prepayment_penalty_structure']
    missing = rules_lib.gaps(
        amount=amount_raw, cltv=cltv_raw, score=score_raw,
        interest_only=interest_only_raw, escrow_waived=escrow_waived_raw,
        reserves=reserves_raw, penalty=penalty_raw
    )
    if missing:
        return rules_lib.unknown(*missing)

    def number(value):
        if isinstance(value, bool):
            return None
        try:
            result = decimal.Decimal(str(value).replace(',', '').replace('$', '').replace('%', '').strip())
            return result if result.is_finite() else None
        except (decimal.InvalidOperation, ValueError, TypeError):
            return None

    amount = number(amount_raw)
    cltv = number(cltv_raw)
    score = number(score_raw)
    reserves = number(reserves_raw)
    interest_only = rules_lib.flag(interest_only_raw)
    escrow_waived = rules_lib.flag(escrow_waived_raw)
    missing = rules_lib.gaps(
        amount=amount, cltv=cltv, score=score, reserves=reserves,
        interest_only=interest_only, escrow_waived=escrow_waived
    )
    if missing:
        return rules_lib.unknown(*missing)

    if interest_only or escrow_waived:
        return False

    if kind == 'rate_term':
        if score < 700 or reserves < 6:
            return False
        if amount == 1000000 or amount == 2000000:
            return rules_lib.unknown('rate_term_loan_amount_tier_confirmation')
        if amount > 2000000:
            return False
        if amount < 1000000:
            if cltv > 70:
                return False
        elif cltv > 65:
            return False
        minimum_years = 2
    else:
        dscr_raw = ctx['LoanCore.dscr_qualification_method']
        missing = rules_lib.gaps(dscr=dscr_raw)
        if missing:
            return rules_lib.unknown(*missing)
        dscr = number(dscr_raw)
        if dscr is None:
            return rules_lib.unknown('LoanCore.dscr_qualification_method')
        if score < 700 or dscr < decimal.Decimal('1.15') or reserves < 6:
            return False
        if amount < 1500000 and cltv > 60:
            return False
        minimum_years = 3

    penalty_years = number(penalty_raw)
    if penalty_years is None and isinstance(penalty_raw, str):
        if re.search(r'not\s+allowed|prohibited', penalty_raw, re.I):
            return True
        match = re.search(r'(\d+(?:\.\d+)?)\s*-?\s*years?', penalty_raw, re.I)
        if match:
            penalty_years = decimal.Decimal(match.group(1))
    if penalty_years is None:
        return rules_lib.unknown('LoanCore.prepayment_penalty_structure')
    return penalty_years >= minimum_years

