import decimal
import rules_lib


def check(ctx):
    amount = ctx['LoanCore.total_loan_amount_usd']
    interest_only_raw = ctx['MortgageLoanInformation.is_interest_only']
    missing = rules_lib.gaps(amount=amount, interest_only=interest_only_raw)
    if missing:
        return rules_lib.unknown(*missing)

    interest_only = rules_lib.flag(interest_only_raw)
    if interest_only is None:
        return rules_lib.unknown('MortgageLoanInformation.is_interest_only')

    amount_number = decimal.Decimal(str(amount))
    purpose = None
    cltv = None
    cltv_limit = None

    if amount_number < decimal.Decimal('200000'):
        purpose = ctx['LoanCore.loan_purpose']
        missing = rules_lib.gaps(purpose=purpose)
        if missing:
            return rules_lib.unknown(*missing)

        if rules_lib.same(purpose, 'purchase'):
            cltv_limit = 80
        elif rules_lib.same(
            purpose,
            'rate & term',
            'refinance rate & term',
            'cash-out',
            'refinance cash-out',
        ):
            cltv_limit = 75

        if cltv_limit is not None:
            cltv = ctx['LoanCore.cltv_percent']
            missing = rules_lib.gaps(cltv=cltv)
            if missing:
                return rules_lib.unknown(*missing)

    if not (decimal.Decimal('100000') <= amount_number <= decimal.Decimal('3000000')):
        return False
    if amount_number % decimal.Decimal('50') != 0:
        return False
    if cltv_limit is not None and cltv > cltv_limit:
        return False
    if interest_only and not (
        decimal.Decimal('250000') <= amount_number <= decimal.Decimal('3000000')
    ):
        return False
    return True

