import rules_lib

def check(ctx):
    amount = ctx['LoanCore.total_loan_amount_usd']
    score = ctx['CreditReport.representative_score']
    purpose = ctx['LoanCore.loan_purpose']
    cltv = ctx['LoanCore.cltv_percent']

    missing = rules_lib.gaps(amount=amount, score=score, purpose=purpose, cltv=cltv)
    if missing:
        return rules_lib.unknown(*missing)

    if amount > 1_000_000 or score < 640:
        return False

    if rules_lib.same(purpose, 'purchase'):
        transaction = 'purchase'
    elif rules_lib.same(purpose, 'refinance', 'rate & term', 'cash-out', 'rate & term refinance', 'cash-out refinance'):
        transaction = 'refinance'
    else:
        return rules_lib.unknown('LoanCore.loan_purpose transaction type')

    if 640 <= score <= 659:
        maximum = 60
    elif 660 <= score <= 699:
        maximum = 65 if transaction == 'purchase' else 60
    elif score == 700:
        maximum = 70 if transaction == 'purchase' else 65
    else:
        return rules_lib.unknown('CreditReport.representative_score printed FICO tier')

    return cltv <= maximum

