def check(ctx):
    purpose = ctx['LoanCore.loan_purpose']
    units = ctx['SubjectProperty.number_of_units']
    occupancy = ctx['SubjectProperty.occupancy_subtype']
    missing = rules_lib.gaps(purpose=purpose, units=units, occupancy=occupancy)
    if missing:
        return rules_lib.unknown(*missing)
    if not isinstance(units, (int, float)) or isinstance(units, bool):
        return False
    return (
        (rules_lib.same(purpose, 'purchase') or rules_lib.same(purpose, 'refinance'))
        and 1 <= units <= 4
        and (rules_lib.same(occupancy, 'investment') or rules_lib.same(occupancy, 'investment property'))
    )

import rules_lib


def check(ctx):
    number_of_units = ctx['SubjectProperty.number_of_units']
    occupancy_subtype = ctx['SubjectProperty.occupancy_subtype']
    loan_purpose = ctx['LoanCore.loan_purpose']
    cltv_percent = ctx['LoanCore.cltv_percent']

    missing = rules_lib.gaps(
        number_of_units=number_of_units,
        occupancy_subtype=occupancy_subtype,
        loan_purpose=loan_purpose,
        cltv_percent=cltv_percent,
    )
    if missing:
        return rules_lib.unknown(*missing)

    return (
        number_of_units in (1, 2, 3, 4)
        and rules_lib.same(occupancy_subtype, 'non-owner occupied')
        and (
            rules_lib.same(loan_purpose, 'purchase')
            or rules_lib.same(loan_purpose, 'refinance')
        )
        and cltv_percent <= 70
    )

