def check(ctx):
    cltv = ctx['LoanCore.cltv_percent']
    missing = rules_lib.gaps(cltv=cltv)
    if missing:
        return rules_lib.unknown(*missing)

    # CLTV at or below 70% is explicitly exempt from rent loss insurance.
    # Above 70% does not establish the other applicability conditions or
    # the substitution details, which are left to a reviewer.
    result = rules_lib.band(cltv, [(70, False)], above=True)
    if result is None:
        return rules_lib.unknown('cltv')
    return result

