def check(ctx):
    io_raw = ctx['MortgageLoanInformation.is_interest_only']
    missing = rules_lib.gaps(is_interest_only=io_raw)
    if missing:
        return rules_lib.unknown(*missing)
    io = rules_lib.flag(io_raw)
    if io is None:
        return rules_lib.unknown('MortgageLoanInformation.is_interest_only')
    if not io:
        return True

    io_10_40_raw = ctx['LoanCore.is_interest_only_10_40']
    missing = rules_lib.gaps(is_interest_only_10_40=io_10_40_raw)
    if missing:
        return rules_lib.unknown(*missing)
    io_10_40 = rules_lib.flag(io_10_40_raw)
    if io_10_40 is None:
        return rules_lib.unknown('LoanCore.is_interest_only_10_40')
    if io_10_40:
        return True

    amount = ctx['LoanCore.total_loan_amount_usd']
    score = ctx['CreditReport.representative_score']
    missing = rules_lib.gaps(loan_amount=amount, representative_score=score)
    if missing:
        return rules_lib.unknown(*missing)

    amount_value = rules_lib.ratio(amount, 1)
    score_value = rules_lib.ratio(score, 1)
    if amount_value is None:
        return rules_lib.unknown('LoanCore.total_loan_amount_usd')
    if score_value is None:
        return rules_lib.unknown('CreditReport.representative_score')
    return amount_value >= 250000 and score_value >= 640

