import rules_lib

def check(ctx):
    cltv = ctx['LoanCore.cltv_percent']
    score = ctx['CreditReport.representative_score']
    method = ctx['LoanCore.dscr_qualification_method']
    purpose = ctx['LoanCore.loan_purpose']
    property_type = ctx['SubjectProperty.property_type']
    state = ctx['SubjectProperty.state']

    uncertain = []

    # The source labels this limit LTV, while the available field is CLTV.
    if not rules_lib.known(cltv):
        uncertain.append('LoanCore.cltv_percent')
    elif cltv > 80.00:
        if not rules_lib.known(property_type):
            uncertain.append('SubjectProperty.property_type')
        elif rules_lib.same(property_type, 'SFR', 'Townhome', 'PUD'):
            pass
        elif rules_lib.same(property_type, 'Warrantable Condo'):
            if not rules_lib.known(state):
                uncertain.append('SubjectProperty.state')
            elif rules_lib.same(state, 'Florida', 'FL'):
                return False
        else:
            return False

    if not rules_lib.known(method):
        uncertain.append('LoanCore.dscr_qualification_method')
        uncertain.append('DSCR')
    elif rules_lib.same(method, 'No Ratio', 'No Ratio DSCR'):
        if not rules_lib.known(score):
            uncertain.append('CreditReport.representative_score')
        elif score < 640:
            return False

        if not rules_lib.known(purpose):
            uncertain.append('LoanCore.loan_purpose')
        else:
            if rules_lib.same(purpose, 'purchase'):
                maximum_cltv = 75
            elif rules_lib.same(purpose, 'rate & term refinance', 'refinance — rate & term', 'refinance rate and term'):
                maximum_cltv = 70
            elif rules_lib.same(purpose, 'cash-out refinance', 'refinance — cash-out', 'refinance cash out'):
                maximum_cltv = 65
            else:
                maximum_cltv = None
                uncertain.append('LoanCore.loan_purpose')

            if maximum_cltv is not None:
                if not rules_lib.known(cltv):
                    uncertain.append('LoanCore.cltv_percent')
                elif cltv > maximum_cltv:
                    return False
    else:
        # No DSCR value is among the permitted fields, so the below-1.0 trigger
        # cannot be determined for a non-No-Ratio qualification method.
        uncertain.append('DSCR')

    if uncertain:
        return rules_lib.unknown(*uncertain)
    return True

