def check(ctx):
    citizenship = ctx['Borrower.citizenship_status']
    missing = rules_lib.gaps(citizenship=citizenship)
    if missing:
        return rules_lib.unknown(*missing)

    if not rules_lib.same(citizenship, 'Foreign National'):
        return True

    occupancy = ctx['SubjectProperty.occupancy_subtype']
    cltv = ctx['LoanCore.cltv_percent']
    purpose = ctx['LoanCore.loan_purpose']
    missing = rules_lib.gaps(occupancy=occupancy, cltv=cltv, purpose=purpose)
    if missing:
        return rules_lib.unknown(*missing)

    if not rules_lib.same(occupancy, 'investment', 'investment property'):
        return False

    if rules_lib.same(purpose, 'purchase'):
        limit = 70
    elif rules_lib.same(
        purpose,
        'rate & term',
        'rate & term refinance',
        'refinance rate & term',
        'cash-out',
        'cash-out refinance',
        'refinance cash-out',
    ):
        limit = 65
    else:
        return rules_lib.unknown('LoanCore.loan_purpose')

    return cltv <= limit

