import decimal
import rules_lib


def check(ctx):
    amount_raw = ctx['LoanCore.total_loan_amount_usd']
    interest_only_raw = ctx['MortgageLoanInformation.is_interest_only']
    delayed_raw = ctx['LoanCore.is_delayed_financing']

    missing = rules_lib.gaps(
        amount=amount_raw,
        interest_only=interest_only_raw,
        delayed_financing=delayed_raw,
    )
    if missing:
        return rules_lib.unknown(*missing)

    interest_only = rules_lib.flag(interest_only_raw)
    delayed_financing = rules_lib.flag(delayed_raw)
    if interest_only is None or delayed_financing is None:
        undecided = []
        if interest_only is None:
            undecided.append('MortgageLoanInformation.is_interest_only')
        if delayed_financing is None:
            undecided.append('LoanCore.is_delayed_financing')
        return rules_lib.unknown(*undecided)

    try:
        amount = decimal.Decimal(str(amount_raw))
        if not amount.is_finite():
            return rules_lib.unknown('LoanCore.total_loan_amount_usd')
    except (decimal.InvalidOperation, TypeError, ValueError):
        return rules_lib.unknown('LoanCore.total_loan_amount_usd')

    if amount < decimal.Decimal('100000') or amount > decimal.Decimal('3000000'):
        return False
    if amount % decimal.Decimal('50') != 0:
        return False
    if interest_only and (amount < decimal.Decimal('250000') or amount > decimal.Decimal('3000000')):
        return False
    if delayed_financing and amount > decimal.Decimal('1500000'):
        return False
    return True

