import re
import rules_lib


def check(ctx):
    penalty = ctx['LoanCore.prepayment_penalty_structure']
    missing = rules_lib.gaps(prepayment_penalty_structure=penalty)
    if missing:
        state = ctx['SubjectProperty.state']
        missing = rules_lib.gaps(prepayment_penalty_structure=penalty, state=state)
        if missing:
            return rules_lib.unknown(*missing)
        if rules_lib.same(state, 'does not allow prepayment penalties', 'state does not allow prepayment penalties'):
            return True
        return rules_lib.unknown('prepayment_penalty_structure')

    years = None
    if isinstance(penalty, str):
        match = re.search(r'(?<![\d.])(\d+)\s*(?:years?|yrs?)\b', penalty, re.IGNORECASE)
        if match:
            years = int(match.group(1))
        else:
            match = re.fullmatch(r'\s*(\d+)(?:\s*[-/]\s*\d+)+\s*', penalty)
            if match:
                years = int(match.group(1))

    if years is not None and years >= 3:
        return True

    state = ctx['SubjectProperty.state']
    missing = rules_lib.gaps(state=state)
    if missing:
        return rules_lib.unknown(*missing)
    if rules_lib.same(state, 'does not allow prepayment penalties', 'state does not allow prepayment penalties'):
        return True
    if years is not None and years < 3 and rules_lib.same(state, 'allows prepayment penalties', 'state allows prepayment penalties'):
        return False
    return rules_lib.unknown('state_law_exception' if years is not None else 'prepayment_penalty_structure', 'state_law_exception')

