def check(ctx):
    score = ctx['CreditReport.representative_score']
    cltv = ctx['LoanCore.cltv_percent']
    purpose = ctx['LoanCore.loan_purpose']

    missing = rules_lib.gaps(score=score, cltv=cltv, purpose=purpose)
    if missing:
        return rules_lib.unknown(*missing)

    if score == 720:
        return rules_lib.unknown('Acra confirmation on score 720 treatment')

    row = rules_lib.band(score, [(699, None), (720, 700), (729, 721)], above=730)
    if row is None:
        return rules_lib.unknown('matrix CLTV row below FICO 700')

    if rules_lib.same(purpose, 'purchase'):
        limit = 80
    elif rules_lib.same(purpose, 'rate & term'):
        limit = 80
    elif rules_lib.same(purpose, 'cash-out'):
        limit = {730: 75, 721: 65, 700: 55}[row]
    else:
        return rules_lib.unknown('LoanCore.loan_purpose')

    meets_limit = rules_lib.close(cltv, cltv, tolerance=0)
    if meets_limit is None:
        return rules_lib.unknown('LoanCore.cltv_percent')
    return cltv <= limit

