def check(ctx):
    listed_raw = ctx['SubjectProperty.listed_for_sale_last_6_months']
    listed = rules_lib.flag(listed_raw)
    if listed is None:
        return rules_lib.unknown('SubjectProperty.listed_for_sale_last_6_months')
    if not listed:
        return True

    occupancy_subtype = ctx['SubjectProperty.occupancy_subtype']
    reserves_months = ctx['RatioSet.reserves_months']
    interest_only_raw = ctx['MortgageLoanInformation.is_interest_only']
    interest_only = rules_lib.flag(interest_only_raw)

    is_investment = rules_lib.same(
        occupancy_subtype, 'investment', 'investment property', 'investor'
    )
    if is_investment:
        has_current_lease_raw = ctx['SubjectProperty.has_current_lease']
        is_vacant_raw = ctx['SubjectProperty.is_vacant']
        has_current_lease = rules_lib.flag(has_current_lease_raw)
        is_vacant = rules_lib.flag(is_vacant_raw)
        missing = rules_lib.gaps(
            occupancy_subtype=occupancy_subtype,
            reserves_months=reserves_months,
            interest_only=interest_only,
            has_current_lease=has_current_lease,
            is_vacant=is_vacant,
        )
    else:
        missing = rules_lib.gaps(
            occupancy_subtype=occupancy_subtype,
            reserves_months=reserves_months,
            interest_only=interest_only,
        )
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.band(-reserves_months, [(-24, True)], above=False) is False:
        return False
    if interest_only:
        return False
    if is_investment and (not has_current_lease or is_vacant):
        return False

    # No permitted case field states whether subordinate financing exists.
    return rules_lib.unknown('subordinate_financing')

