import rules_lib


def check(ctx):
    loan_amount = ctx['LoanCore.total_loan_amount_usd']
    is_delayed_financing = ctx['LoanCore.is_delayed_financing']

    missing = rules_lib.gaps(
        loan_amount=loan_amount,
        is_delayed_financing=is_delayed_financing,
    )
    if missing:
        return rules_lib.unknown(*missing)

    delayed = rules_lib.flag(is_delayed_financing)
    if delayed is None:
        return rules_lib.unknown('is_delayed_financing')

    try:
        amount = decimal.Decimal(str(loan_amount))
        if not amount.is_finite():
            return rules_lib.unknown('loan_amount')
        return (
            amount >= decimal.Decimal('100000')
            and amount <= decimal.Decimal('2000000')
            and amount % decimal.Decimal('50') == 0
            and (not delayed or amount <= decimal.Decimal('1500000'))
        )
    except (decimal.InvalidOperation, TypeError, ValueError):
        return rules_lib.unknown('loan_amount')

